// src/pages/admin/AdminEmailIntegration.js
import React, { useEffect, useMemo, useState } from "react";
import api from "../../api";

const PROVIDERS = [
  { value: "mailgun", label: "Mailgun" },
  { value: "sendgrid", label: "SendGrid" },
  { value: "postmark", label: "Postmark" },
  { value: "ses", label: "Amazon SES" },
];

function Toast({ toast, onClose }) {
  if (!toast) return null;
  return (
    <div
      style={{
        position: "fixed",
        right: 18,
        bottom: 18,
        zIndex: 9999,
        maxWidth: 520,
        padding: "12px 14px",
        borderRadius: 12,
        background:
          toast.type === "error"
            ? "rgba(255,90,90,.15)"
            : "rgba(79,140,255,.15)",
        border: "1px solid rgba(255,255,255,.14)",
        color: "rgba(255,255,255,.92)",
        backdropFilter: "blur(10px)",
        cursor: "pointer",
      }}
      onClick={onClose}
      title="Click to close"
    >
      <div style={{ fontWeight: 700, marginBottom: 4 }}>
        {toast.type === "error" ? "Error" : "Success"}
      </div>
      <div style={{ opacity: 0.9 }}>{toast.message}</div>
    </div>
  );
}

export default function AdminEmailIntegration() {
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState(null);

  const [connection, setConnection] = useState(null);

  const [provider, setProvider] = useState("mailgun");

  // Provider fields (Mailgun)
  const [region, setRegion] = useState("us"); // us | eu
  const [apiKey, setApiKey] = useState("");
  const [domain, setDomain] = useState("");
  const [fromEmail, setFromEmail] = useState("");
  const [fromName, setFromName] = useState("Bishop Robertson TV");

  function showToast(type, message) {
    setToast({ type, message });
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 3200);
  }

  async function load() {
    setLoading(true);
    try {
      const r = await api.get("/admin/email/connection");
      setConnection(r.data?.connection || null);
    } catch {
      setConnection(null);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  const providerLabel = useMemo(() => {
    const found = PROVIDERS.find((p) => p.value === String(provider));
    return found ? found.label : provider;
  }, [provider]);

  async function onConnect(e) {
    e.preventDefault();
    if (busy) return;

    const p = String(provider || "")
      .trim()
      .toLowerCase();

    if (p === "mailgun") {
      if (!apiKey.trim())
        return showToast("error", "Mailgun API Key is required.");
      if (!domain.trim())
        return showToast("error", "Mailgun Domain is required.");
      if (!fromEmail.trim())
        return showToast("error", "From Email is required.");
    } else {
      if (!apiKey.trim()) return showToast("error", "API Key is required.");
      if (!fromEmail.trim())
        return showToast("error", "From Email is required.");
    }

    setBusy(true);
    try {
      // Send BOTH naming styles so backend/worker won’t mismatch.
      await api.post("/admin/email/connect", {
        provider: p,
        secrets: {
          // mailgun common
          region: (region || "us").trim().toLowerCase(),
          domain: domain.trim() || null,

          // snake_case (backend stores these)
          api_key: apiKey.trim(),
          from_email: fromEmail.trim(),
          from_name: (fromName.trim() || "Bishop Robertson TV").trim(),

          // camelCase (older frontend/worker variants)
          apiKey: apiKey.trim(),
          fromEmail: fromEmail.trim(),
          fromName: (fromName.trim() || "Bishop Robertson TV").trim(),
        },
      });

      showToast("success", `${providerLabel} connected.`);
      setApiKey("");
      await load();
    } catch (e2) {
      showToast(
        "error",
        e2?.response?.data?.error || "Failed to connect provider.",
      );
    } finally {
      setBusy(false);
    }
  }

  async function onDisconnect(e) {
    // IMPORTANT: prevent form-submit behavior if this button ever ends up inside a <form>
    if (e?.preventDefault) e.preventDefault();
    if (busy) return;

    setBusy(true);
    try {
      await api.post("/admin/email/disconnect");
      showToast("success", "Disconnected.");
      await load();
    } catch (e2) {
      showToast("error", e2?.response?.data?.error || "Failed to disconnect.");
    } finally {
      setBusy(false);
    }
  }

  async function onTest(e) {
    if (e?.preventDefault) e.preventDefault();
    if (busy) return;

    setBusy(true);
    try {
      const r = await api.post("/admin/email/test");
      showToast("success", `Test OK (${r.data?.provider || "connected"})`);
    } catch (e2) {
      showToast("error", e2?.response?.data?.error || "Test failed.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ padding: 18 }}>
      <h2 style={{ margin: "6px 0 14px" }}>Email API Integration</h2>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        {/* Current connection */}
        <div
          style={{
            padding: 14,
            borderRadius: 14,
            border: "1px solid rgba(255,255,255,.12)",
            background: "rgba(255,255,255,.04)",
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 10 }}>
            Current Provider
          </div>

          {loading ? (
            <div style={{ opacity: 0.7 }}>Loading…</div>
          ) : connection ? (
            <>
              <div style={{ marginBottom: 8 }}>
                <div style={{ opacity: 0.7, fontSize: 12 }}>Provider</div>
                <div
                  style={{ fontSize: 16, fontWeight: 800, letterSpacing: 0.2 }}
                >
                  {String(connection.provider || "").toUpperCase()}
                </div>
              </div>

              <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                {/* ✅ force type=button so it never submits any form */}
                <button
                  type="button"
                  className="btn"
                  onClick={onTest}
                  disabled={busy}
                >
                  {busy ? "Working…" : "Test Connection"}
                </button>
                <button
                  type="button"
                  className="btn btn-danger"
                  onClick={onDisconnect}
                  disabled={busy}
                >
                  {busy ? "Working…" : "Disconnect"}
                </button>
              </div>

              <div style={{ opacity: 0.6, marginTop: 10, fontSize: 12 }}>
                Active: {connection.is_active ? "Yes" : "No"}
              </div>

              <div style={{ opacity: 0.55, marginTop: 8, fontSize: 12 }}>
                Tip: make sure the <code>emailWorker</code> process is running
                for sends to complete.
              </div>
            </>
          ) : (
            <div style={{ opacity: 0.75 }}>
              No email provider connected yet. Use the form to connect one.
            </div>
          )}
        </div>

        {/* Connect form */}
        <form
          onSubmit={onConnect}
          style={{
            padding: 14,
            borderRadius: 14,
            border: "1px solid rgba(255,255,255,.12)",
            background: "rgba(255,255,255,.04)",
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 10 }}>
            Connect Provider
          </div>

          <label style={{ display: "block", marginBottom: 10 }}>
            <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
              Provider
            </div>
            <select
              value={provider}
              onChange={(e) => setProvider(e.target.value)}
              style={{ width: "100%", padding: 10, borderRadius: 10 }}
            >
              {PROVIDERS.map((p) => (
                <option key={p.value} value={p.value}>
                  {p.label}
                </option>
              ))}
            </select>
          </label>

          {/* Mailgun region (matches what you’re using) */}
          {String(provider).toLowerCase() === "mailgun" ? (
            <label style={{ display: "block", marginBottom: 10 }}>
              <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
                Region
              </div>
              <select
                value={region}
                onChange={(e) => setRegion(e.target.value)}
                style={{ width: "100%", padding: 10, borderRadius: 10 }}
              >
                <option value="us">US</option>
                <option value="eu">EU</option>
              </select>
              <div style={{ opacity: 0.6, marginTop: 6, fontSize: 12 }}>
                Most accounts are US. Use EU only if your Mailgun domain is
                EU-hosted.
              </div>
            </label>
          ) : null}

          <label style={{ display: "block", marginBottom: 10 }}>
            <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
              {String(provider).toLowerCase() === "mailgun"
                ? "Mailgun API Key"
                : "API Key"}
            </div>
            <input
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              type="password"
              autoComplete="current-password"
              placeholder="••••••••••••"
              style={{ width: "100%", padding: 10, borderRadius: 10 }}
            />
          </label>

          <label style={{ display: "block", marginBottom: 10 }}>
            <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
              {String(provider).toLowerCase() === "mailgun"
                ? "Mailgun Domain"
                : "Domain (optional)"}
            </div>
            <input
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="mg.yourdomain.com"
              style={{ width: "100%", padding: 10, borderRadius: 10 }}
            />
            {String(provider).toLowerCase() === "mailgun" ? (
              <div style={{ opacity: 0.6, marginTop: 6, fontSize: 12 }}>
                Example: <code>sandboxXXXX.mailgun.org</code> or your verified
                domain.
              </div>
            ) : null}
          </label>

          <div
            style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}
          >
            <label style={{ display: "block", marginBottom: 10 }}>
              <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
                From Name
              </div>
              <input
                value={fromName}
                onChange={(e) => setFromName(e.target.value)}
                placeholder="Bishop Robertson TV"
                style={{ width: "100%", padding: 10, borderRadius: 10 }}
              />
            </label>

            <label style={{ display: "block", marginBottom: 10 }}>
              <div style={{ opacity: 0.7, fontSize: 12, marginBottom: 6 }}>
                From Email
              </div>
              <input
                value={fromEmail}
                onChange={(e) => setFromEmail(e.target.value)}
                placeholder="no-reply@yourdomain.com"
                style={{ width: "100%", padding: 10, borderRadius: 10 }}
              />
            </label>
          </div>

          <button className="btn btn-primary" type="submit" disabled={busy}>
            {busy ? "Saving…" : "Connect"}
          </button>

          <div style={{ opacity: 0.6, marginTop: 10, fontSize: 12 }}>
            Admin-only. Credentials are stored encrypted on the backend.
          </div>
        </form>
      </div>

      <Toast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}
